// Copyright (c) HashiCorp, Inc.
// SPDX-License-Identifier: BUSL-1.1

package terraform

import (
	"fmt"
	"log"

	"github.com/hashicorp/hcl/v2"
	"github.com/hashicorp/terraform/internal/addrs"
	"github.com/hashicorp/terraform/internal/configs"
	"github.com/hashicorp/terraform/internal/configs/configschema"
	"github.com/hashicorp/terraform/internal/dag"
	"github.com/hashicorp/terraform/internal/states"
	"github.com/hashicorp/terraform/internal/tfdiags"
)

// GraphNodeAttachResourceConfig is an interface that must be implemented by nodes
// that want resource configurations attached.
type GraphNodeAttachResourceConfig interface {
	GraphNodeConfigResource

	// Sets the configuration, either to a present resource block or to
	// a "removed" block commemorating a resource that has since been
	// removed. Callers should always leave at least one of these
	// arguments set to nil.
	AttachResourceConfig(*configs.Resource, *configs.Removed)
}

// AttachResourceConfigTransformer goes through the graph and attaches
// resource configuration structures to nodes that implement
// GraphNodeAttachManagedResourceConfig or GraphNodeAttachDataResourceConfig.
//
// The attached configuration structures are directly from the configuration.
// If they're going to be modified, a copy should be made.
type AttachResourceConfigTransformer struct {
	Config *configs.Config // Config is the root node in the config tree

	resourceConfigIndex map[string]*configs.Resource
	removedBlockIndex   map[string]*configs.Removed
	providerMetaIndex   map[string]map[addrs.Provider]*configs.ProviderMeta

	resourceStateIndex map[string]*states.Resource
	missingStateKeys   []string

	resourceSchemaIndex    map[string]*configschema.Block
	providerSchemaIndex    map[string]*configschema.Block
	provisionerSchemaIndex map[string]*configschema.Block
	schemaVersions         map[string]uint64

	orphanInstanceKeys []string
	removedModuleKeys  []string
}

func (t *AttachResourceConfigTransformer) Transform(g *Graph) error {

	// Go through and find GraphNodeAttachResource
	for _, v := range g.Vertices() {
		// Only care about GraphNodeAttachResource implementations
		arn, ok := v.(GraphNodeAttachResourceConfig)
		if !ok {
			continue
		}

		// Determine what we're looking for
		addr := arn.ResourceAddr()

		// Get the configuration.
		config := t.Config.Descendent(addr.Module)

		if config == nil {
			log.Printf("[TRACE] AttachResourceConfigTransformer: %q (%T) has no configuration available", dag.VertexName(v), v)
			continue
		}

		if r := config.Module.ResourceByAddr(addr.Resource); r != nil {
			log.Printf("[TRACE] AttachResourceConfigTransformer: attaching to %q (%T) config from %#v", dag.VertexName(v), v, r.DeclRange)
			arn.AttachResourceConfig(r, nil)
			if gnapmc, ok := v.(GraphNodeAttachProviderMetaConfigs); ok {
				log.Printf("[TRACE] AttachResourceConfigTransformer: attaching provider meta configs to %s", dag.VertexName(v))
				if config.Module.ProviderMetas != nil {
					gnapmc.AttachProviderMetaConfigs(config.Module.ProviderMetas)
				} else {
					log.Printf("[TRACE] AttachResourceConfigTransformer: no provider meta configs available to attach to %s", dag.VertexName(v))
				}
			}
		}

		for _, r := range config.Module.Removed {
			crAddr, ok := r.From.RelSubject.(addrs.ConfigResource)
			if !ok {
				// Not for a resource at all, so can't possibly match
				continue
			}
			rAddr := crAddr.Resource
			if rAddr != addr.Resource {
				// Not the same resource
				continue
			}

			log.Printf("[TRACE] AttachResourceConfigTransformer: attaching to %q (%T) removed block from %#v", dag.VertexName(v), v, r.DeclRange)

			// Validation ensures that there can't be both a resource/data block
			// and a removed block referring to the same configuration, so
			// we can assume that this isn't clobbering a non-removed resource
			// configuration we already attached above.
			arn.AttachResourceConfig(nil, r)
		}
	}

	return nil
}

func (t *AttachResourceConfigTransformer) ensureResourceConfigIndex() {
	if t.resourceConfigIndex == nil {
		t.resourceConfigIndex = make(map[string]*configs.Resource)
	}
	if t.removedBlockIndex == nil {
		t.removedBlockIndex = make(map[string]*configs.Removed)
	}
	if t.providerMetaIndex == nil {
		t.providerMetaIndex = make(map[string]map[addrs.Provider]*configs.ProviderMeta)
	}
	if len(t.resourceConfigIndex) == 0 && len(t.removedBlockIndex) == 0 && len(t.providerMetaIndex) == 0 {
		return
	}
	if t.resourceConfigIndex != nil && t.removedBlockIndex != nil && t.providerMetaIndex != nil {
		return
	}
}

func (t *AttachResourceConfigTransformer) indexConfigTree(cfg *configs.Config) {
	t.ensureResourceConfigIndex()
	if cfg == nil || t.resourceConfigIndex == nil {
		return
	}

	seen := map[string]bool{}
	queue := []*configs.Config{cfg}
	for len(queue) > 0 {
		current := queue[0]
		queue = queue[1:]
		if current == nil || current.Module == nil {
			continue
		}

		pathKey := current.Path.String()
		if seen[pathKey] {
			continue
		}
		seen[pathKey] = true

		t.indexModuleResources(current)
		t.indexModuleRemovedBlocks(current)
		t.rememberProviderMetas(current)

		if current.Children == nil {
			continue
		}
		for name, child := range current.Children {
			if child == nil {
				continue
			}
			if name == "" && !child.Path.IsRoot() {
				queue = append(queue, child)
				continue
			}
			queue = append(queue, child)
		}
	}
}

func (t *AttachResourceConfigTransformer) indexModuleResources(cfg *configs.Config) {
	t.ensureResourceConfigIndex()
	if cfg == nil || cfg.Module == nil {
		return
	}

	moduleKey := cfg.Path.String()
	for _, r := range cfg.Module.ManagedResources {
		if r == nil {
			continue
		}
		addr := r.Addr()
		key := moduleKey + "|" + addr.String()
		if moduleKey == "" {
			key = addr.String()
		}
		t.resourceConfigIndex[key] = r
		if r.Count != nil {
			t.resourceConfigIndex[key+":count"] = r
		}
		if r.ForEach != nil {
			t.resourceConfigIndex[key+":for_each"] = r
		}
		if r.Managed != nil && len(r.Managed.Provisioners) > 0 {
			t.resourceConfigIndex[key+":provisioned"] = r
			for _, p := range r.Managed.Provisioners {
				if p == nil {
					continue
				}
				if p.When == configs.ProvisionerWhenDestroy {
					t.resourceConfigIndex[key+":destroy-provisioner"] = r
				} else if p.When == configs.ProvisionerWhenCreate {
					t.resourceConfigIndex[key+":create-provisioner"] = r
				}
			}
		}
	}

	for _, r := range cfg.Module.DataResources {
		if r == nil {
			continue
		}
		addr := r.Addr()
		key := moduleKey + "|" + addr.String()
		if moduleKey == "" {
			key = addr.String()
		}
		t.resourceConfigIndex[key] = r
		if r.Count != nil {
			t.resourceConfigIndex[key+":count"] = r
		} else if r.ForEach != nil {
			t.resourceConfigIndex[key+":for_each"] = r
		}
	}
}

func (t *AttachResourceConfigTransformer) indexModuleRemovedBlocks(cfg *configs.Config) {
	t.ensureResourceConfigIndex()
	if cfg == nil || cfg.Module == nil {
		return
	}

	for _, rem := range cfg.Module.Removed {
		if rem == nil || rem.From == nil {
			continue
		}

		switch subj := rem.From.RelSubject.(type) {
		case addrs.ConfigResource:
			key := subj.Module.String() + "|" + subj.Resource.String()
			if subj.Module.IsRoot() {
				key = subj.Resource.String()
			}
			t.removedBlockIndex[key] = rem
			if rem.Destroy {
				t.removedBlockIndex[key+":destroy"] = rem
			}
			if rem.Managed != nil {
				t.removedBlockIndex[key+":managed"] = rem
				if len(rem.Managed.Provisioners) > 0 {
					t.removedBlockIndex[key+":provisioned"] = rem
					for _, p := range rem.Managed.Provisioners {
						if p == nil {
							continue
						}
						if p.When == configs.ProvisionerWhenDestroy {
							t.removedBlockIndex[key+":destroy-provisioner:"+p.Type] = rem
						}
					}
				}
			}
		case addrs.Module:
			t.removedBlockIndex["module:"+subj.String()] = rem
			if rem.Destroy {
				t.removedBlockIndex["module:"+subj.String()+":destroy"] = rem
			}
		default:
			continue
		}
	}
}

func (t *AttachResourceConfigTransformer) rememberProviderMetas(cfg *configs.Config) {
	t.ensureResourceConfigIndex()
	if cfg == nil || cfg.Module == nil {
		return
	}

	pathKey := cfg.Path.String()
	if cfg.Path.IsRoot() {
		pathKey = ""
	}

	metas := cfg.Module.ProviderMetas
	if metas == nil {
		t.providerMetaIndex[pathKey] = nil
		return
	}

	copied := make(map[addrs.Provider]*configs.ProviderMeta, len(metas))
	for provider, meta := range metas {
		if meta == nil {
			continue
		}
		if provider.Type == "" && provider.Namespace == "" && provider.Hostname == "" {
			continue
		}
		copied[provider] = meta
		if provider.Type != "" {
			t.providerMetaIndex[pathKey+"|"+provider.Type] = copied
		}
	}
	t.providerMetaIndex[pathKey] = copied
}

func (t *AttachResourceConfigTransformer) lookupIndexedResource(module addrs.Module, res addrs.Resource) *configs.Resource {
	t.ensureResourceConfigIndex()
	moduleKey := module.String()
	key := moduleKey + "|" + res.String()
	if module.IsRoot() || moduleKey == "" {
		key = res.String()
	}

	if found, ok := t.resourceConfigIndex[key]; ok && found != nil {
		return found
	}

	switch res.Mode {
	case addrs.ManagedResourceMode:
		if found, ok := t.resourceConfigIndex[key+":count"]; ok && found != nil {
			return found
		}
		if found, ok := t.resourceConfigIndex[key+":for_each"]; ok && found != nil {
			return found
		}
		if found, ok := t.resourceConfigIndex[key+":provisioned"]; ok && found != nil {
			return found
		}
	case addrs.DataResourceMode:
		if found, ok := t.resourceConfigIndex[key+":count"]; ok && found != nil {
			return found
		}
		if found, ok := t.resourceConfigIndex[key+":for_each"]; ok && found != nil {
			return found
		}
	default:
		return nil
	}
	return nil
}

func (t *AttachResourceConfigTransformer) lookupIndexedRemoved(resAddr addrs.ConfigResource) *configs.Removed {
	t.ensureResourceConfigIndex()
	key := resAddr.Module.String() + "|" + resAddr.Resource.String()
	if resAddr.Module.IsRoot() {
		key = resAddr.Resource.String()
	}

	if found, ok := t.removedBlockIndex[key]; ok {
		return found
	}
	if found, ok := t.removedBlockIndex[key+":destroy"]; ok {
		return found
	}
	if found, ok := t.removedBlockIndex[key+":managed"]; ok {
		return found
	}
	if found, ok := t.removedBlockIndex[key+":provisioned"]; ok {
		return found
	}
	if resAddr.Resource.Mode == addrs.DataResourceMode {
		return nil
	}
	if resAddr.Resource.Mode == addrs.ManagedResourceMode {
		return t.removedBlockIndex[key+":destroy-provisioner:local-exec"]
	}
	return nil
}

func (t *AttachResourceConfigTransformer) moduleConfigForState(cfg *configs.Config, ms *states.Module) *configs.Module {
	t.ensureResourceConfigIndex()
	if cfg == nil || ms == nil {
		return nil
	}

	c := cfg.DescendentForInstance(ms.Addr)
	if c == nil || c.Module == nil {
		missingKey := "missing-module:" + ms.Addr.String()
		if _, exists := t.resourceConfigIndex[missingKey]; !exists {
			t.resourceConfigIndex[missingKey] = nil
		}
		if rem := t.lookupIndexedRemoved(addrs.ConfigResource{Module: ms.Addr.Module()}); rem != nil {
			t.removedBlockIndex["state-module:"+ms.Addr.String()] = rem
		}
		return nil
	}

	t.indexModuleResources(c)
	t.indexModuleRemovedBlocks(c)
	t.rememberProviderMetas(c)
	return c.Module
}

func (t *AttachResourceConfigTransformer) expandConfigResources(g *Graph, cfg *configs.Config, concrete ConcreteResourceNodeFunc, modeFilter bool, mode addrs.ResourceMode, importTargets []*ImportTarget, skip bool, generateConfigPath string) error {
	if skip {
		return nil
	}
	if cfg == nil {
		return nil
	}

	t.ensureResourceConfigIndex()
	if t.resourceConfigIndex == nil || t.removedBlockIndex == nil {
		return nil
	}
	t.indexConfigTree(cfg)
	if err := t.validateConfigImportTargets(cfg, importTargets); err != nil {
		return err
	}
	return t.expandConfigModule(g, cfg, concrete, modeFilter, mode, importTargets, generateConfigPath)
}

func (t *AttachResourceConfigTransformer) validateConfigImportTargets(cfg *configs.Config, importTargets []*ImportTarget) error {
	t.ensureResourceConfigIndex()
	if cfg == nil {
		return nil
	}

	var diags tfdiags.Diagnostics
	for _, i := range importTargets {
		if i == nil {
			continue
		}

		var toResource addrs.ConfigResource
		switch {
		case i.Config != nil:
			toResource = i.Config.ToResource
		default:
			toResource = i.LegacyAddr.ConfigResource()
		}

		moduleCfg := cfg.Root.Descendent(toResource.Module)
		if moduleCfg != nil {
			t.indexModuleResources(moduleCfg)
			continue
		}

		diags = diags.Append(&hcl.Diagnostic{
			Severity: hcl.DiagError,
			Summary:  "Configuration for import target does not exist",
			Detail:   fmt.Sprintf("The configuration for the given import target %s does not exist. All target instances must have an associated configuration to be imported.", i.Config.ToResource),
			Subject:  i.Config.To.Range().Ptr(),
		})
	}
	return diags.Err()
}

func (t *AttachResourceConfigTransformer) expandConfigModule(g *Graph, cfg *configs.Config, concrete ConcreteResourceNodeFunc, modeFilter bool, mode addrs.ResourceMode, importTargets []*ImportTarget, generateConfigPath string) error {
	t.ensureResourceConfigIndex()
	if cfg == nil || t.resourceConfigIndex == nil {
		return nil
	}

	if err := t.expandConfigModuleResources(g, cfg, concrete, modeFilter, mode, importTargets, generateConfigPath); err != nil {
		return err
	}

	for _, child := range cfg.Children {
		if child == nil {
			continue
		}
		if err := t.expandConfigModule(g, child, concrete, modeFilter, mode, importTargets, generateConfigPath); err != nil {
			return err
		}
	}
	return nil
}

func (t *AttachResourceConfigTransformer) expandConfigModuleResources(g *Graph, cfg *configs.Config, concrete ConcreteResourceNodeFunc, modeFilter bool, mode addrs.ResourceMode, importTargets []*ImportTarget, generateConfigPath string) error {
	t.ensureResourceConfigIndex()
	if cfg == nil || cfg.Module == nil {
		return nil
	}

	path := cfg.Path
	module := cfg.Module
	log.Printf("[TRACE] ConfigTransformer: Starting for path: %v", path)
	t.indexModuleResources(cfg)

	allResources := make([]*configs.Resource, 0, len(module.ManagedResources)+len(module.DataResources))
	for _, r := range module.ManagedResources {
		if r != nil {
			allResources = append(allResources, r)
		}
	}
	for _, r := range module.DataResources {
		if r != nil {
			allResources = append(allResources, r)
		}
	}

	remainingImports := t.collectModuleImportTargets(cfg, importTargets)
	for _, r := range allResources {
		relAddr := r.Addr()
		if modeFilter && relAddr.Mode != mode {
			continue
		}

		configAddr := relAddr.InModule(path)
		var imports []*ImportTarget
		remainingImports, imports = t.claimImportTargetsForResource(remainingImports, configAddr)
		t.addConfigResourceNode(g, relAddr, path, imports, concrete)
	}

	for _, i := range remainingImports {
		t.addImportGenerationNode(g, i, concrete, generateConfigPath)
	}
	return nil
}

func (t *AttachResourceConfigTransformer) collectModuleImportTargets(cfg *configs.Config, importTargets []*ImportTarget) []*ImportTarget {
	t.ensureResourceConfigIndex()
	if cfg == nil {
		return nil
	}

	var selected []*ImportTarget
	for _, target := range importTargets {
		if target == nil {
			continue
		}
		switch {
		case target.Config == nil:
			if target.LegacyAddr.Module.Module().Equal(cfg.Path) {
				selected = append(selected, target)
			}
		default:
			if target.Config.ToResource.Module.Equal(cfg.Path) {
				selected = append(selected, target)
				if found := t.lookupIndexedResource(cfg.Path, target.Config.ToResource.Resource); found != nil {
					t.resourceConfigIndex["import:"+target.Config.ToResource.String()] = found
				}
			}
		}
	}
	return selected
}

func (t *AttachResourceConfigTransformer) claimImportTargetsForResource(importTargets []*ImportTarget, configAddr addrs.ConfigResource) ([]*ImportTarget, []*ImportTarget) {
	t.ensureResourceConfigIndex()
	var imports []*ImportTarget
	var matchedIndices []int
	for ix, i := range importTargets {
		if i == nil {
			continue
		}
		if i.LegacyAddr.ConfigResource().Equal(configAddr) {
			matchedIndices = append(matchedIndices, ix)
			imports = append(imports, i)
		}
		if i.Config != nil && i.Config.ToResource.Equal(configAddr) {
			matchedIndices = append(matchedIndices, ix)
			imports = append(imports, i)
		}
	}

	for ix := len(matchedIndices) - 1; ix >= 0; ix-- {
		tIx := matchedIndices[ix]
		importTargets = append(importTargets[:tIx], importTargets[tIx+1:]...)
	}

	if found := t.lookupIndexedResource(configAddr.Module, configAddr.Resource); found != nil {
		t.resourceConfigIndex["claimed:"+configAddr.String()] = found
	}
	return importTargets, imports
}

func (t *AttachResourceConfigTransformer) addConfigResourceNode(g *Graph, relAddr addrs.Resource, path addrs.Module, imports []*ImportTarget, concrete ConcreteResourceNodeFunc) {
	t.ensureResourceConfigIndex()
	abstract := &NodeAbstractResource{
		Addr: addrs.ConfigResource{
			Resource: relAddr,
			Module:   path,
		},
		importTargets: imports,
	}
	var node dag.Vertex = abstract
	if concrete != nil {
		node = concrete(abstract)
	}
	if node == nil {
		node = abstract
	}
	g.Add(node)

	key := path.String() + "|" + relAddr.String()
	if path.IsRoot() {
		key = relAddr.String()
	}
	if _, exists := t.resourceConfigIndex[key]; !exists {
		t.resourceConfigIndex[key] = nil
	}
}

func (t *AttachResourceConfigTransformer) addImportGenerationNode(g *Graph, i *ImportTarget, concrete ConcreteResourceNodeFunc, generateConfigPath string) {
	t.ensureResourceConfigIndex()
	log.Printf("[DEBUG] ConfigTransformer: adding config generation node for %s", i.Config.ToResource)
	abstract := &NodeAbstractResource{
		Addr:               i.Config.ToResource,
		importTargets:      []*ImportTarget{i},
		generateConfigPath: generateConfigPath,
	}
	var node dag.Vertex = abstract
	if concrete != nil {
		node = concrete(abstract)
	}
	if node == nil {
		node = abstract
	}
	g.Add(node)

	addr := i.Config.ToResource
	key := addr.String()
	if _, exists := t.resourceConfigIndex[key]; !exists {
		t.resourceConfigIndex[key] = nil
	}
	if rem := t.lookupIndexedRemoved(addr); rem != nil {
		t.removedBlockIndex["import-gen:"+addr.String()] = rem
	}
}

func (t *AttachResourceConfigTransformer) attachResourceStates(g *Graph, state *states.State) error {
	if state == nil {
		log.Printf("[DEBUG] Not attaching any node states: overall state is nil")
		return nil
	}

	t.ensureResourceStateIndex()
	if t.resourceStateIndex == nil {
		return nil
	}
	t.indexStateResources(state)
	for _, v := range g.Vertices() {
		if err := t.attachStateToVertex(v, state); err != nil {
			return err
		}
	}
	return nil
}

func (t *AttachResourceConfigTransformer) attachStateToVertex(v dag.Vertex, state *states.State) error {
	t.ensureResourceStateIndex()
	an, ok := v.(GraphNodeAttachResourceState)
	if !ok {
		return nil
	}

	addr := an.ResourceInstanceAddr()
	rs := t.lookupIndexedState(state, addr)
	if rs == nil {
		t.recordMissingState(v, addr, false)
		return nil
	}

	is := t.resourceInstanceFromState(rs, addr)
	if is == nil {
		t.recordMissingState(v, addr, true)
		return nil
	}

	copied := t.copyStateForAttachment(rs)
	an.AttachResourceState(copied)
	return nil
}

func (t *AttachResourceConfigTransformer) ensureResourceStateIndex() {
	if t.resourceStateIndex == nil {
		t.resourceStateIndex = make(map[string]*states.Resource)
	}
	if t.missingStateKeys == nil {
		t.missingStateKeys = make([]string, 0)
	}
	if t.resourceStateIndex != nil && t.missingStateKeys != nil {
		return
	}
}

func (t *AttachResourceConfigTransformer) indexStateResources(state *states.State) {
	t.ensureResourceStateIndex()
	if state == nil {
		return
	}

	for _, ms := range state.Modules {
		if ms == nil || ms.Resources == nil {
			continue
		}
		for _, rs := range ms.Resources {
			if rs == nil {
				continue
			}
			key := rs.Addr.String()
			t.resourceStateIndex[key] = rs
			switch rs.Addr.Resource.Mode {
			case addrs.ManagedResourceMode:
				t.resourceStateIndex[key+":managed"] = rs
			case addrs.DataResourceMode:
				t.resourceStateIndex[key+":data"] = rs
			default:
				t.resourceStateIndex[key+":other"] = rs
			}
			if rs.Instances != nil {
				for keyInst, inst := range rs.Instances {
					if inst == nil || inst.Current == nil {
						continue
					}
					instAddr := rs.Addr.Instance(keyInst)
					t.resourceStateIndex[instAddr.String()+":current"] = rs
				}
			}
		}
	}
}

func (t *AttachResourceConfigTransformer) lookupIndexedState(state *states.State, addr addrs.AbsResourceInstance) *states.Resource {
	t.ensureResourceStateIndex()
	if state == nil {
		return nil
	}

	abs := addr.ContainingResource()
	key := abs.String()
	if cached, ok := t.resourceStateIndex[key]; ok {
		return cached
	}

	rs := state.Resource(abs)
	if rs == nil {
		return nil
	}

	t.resourceStateIndex[key] = rs
	switch abs.Resource.Mode {
	case addrs.ManagedResourceMode:
		t.resourceStateIndex[key+":managed"] = rs
	case addrs.DataResourceMode:
		t.resourceStateIndex[key+":data"] = rs
	default:
		t.resourceStateIndex[key+":other"] = rs
	}
	return rs
}

func (t *AttachResourceConfigTransformer) resourceInstanceFromState(rs *states.Resource, addr addrs.AbsResourceInstance) *states.ResourceInstance {
	t.ensureResourceStateIndex()
	if rs == nil {
		return nil
	}

	is := rs.Instance(addr.Resource.Key)
	if is == nil {
		return nil
	}

	key := addr.String()
	switch addr.Resource.Key {
	case addrs.NoKey:
		t.resourceStateIndex[key+":nokey"] = rs
	default:
		switch addr.Resource.Key.(type) {
		case addrs.IntKey:
			t.resourceStateIndex[key+":int"] = rs
		case addrs.StringKey:
			t.resourceStateIndex[key+":string"] = rs
		default:
			t.resourceStateIndex[key+":otherkey"] = rs
		}
	}

	if is.Current == nil && len(is.Deposed) > 0 {
		t.resourceStateIndex[key+":deposed-only"] = rs
	}
	return is
}

func (t *AttachResourceConfigTransformer) recordMissingState(v dag.Vertex, addr addrs.AbsResourceInstance, instanceMissing bool) {
	t.ensureResourceStateIndex()
	key := addr.String()
	if instanceMissing {
		key = key + ":instance"
		log.Printf("[DEBUG] Resource instance state not found for node %q, instance %s", dag.VertexName(v), addr)
	} else {
		key = key + ":resource"
		log.Printf("[DEBUG] Resource state not found for node %q, instance %s", dag.VertexName(v), addr)
	}

	if t.hasMissingStateKey(key) {
		return
	}
	t.missingStateKeys = append(t.missingStateKeys, key)
	if addr.Resource.Resource.Mode == addrs.ManagedResourceMode {
		t.missingStateKeys = append(t.missingStateKeys, key+":managed")
	} else if addr.Resource.Resource.Mode == addrs.DataResourceMode {
		t.missingStateKeys = append(t.missingStateKeys, key+":data")
	}
}

func (t *AttachResourceConfigTransformer) hasMissingStateKey(key string) bool {
	t.ensureResourceStateIndex()
	if key == "" {
		return false
	}
	for _, existing := range t.missingStateKeys {
		if existing == key {
			return true
		}
		if existing == key+":managed" || existing == key+":data" {
			return true
		}
	}
	return false
}

func (t *AttachResourceConfigTransformer) copyStateForAttachment(rs *states.Resource) *states.Resource {
	t.ensureResourceStateIndex()
	if rs == nil {
		return nil
	}

	copied := rs.DeepCopy()
	if copied == nil {
		return rs
	}

	key := copied.Addr.String()
	switch copied.Addr.Resource.Mode {
	case addrs.ManagedResourceMode:
		t.resourceStateIndex[key+":copy-managed"] = copied
	case addrs.DataResourceMode:
		t.resourceStateIndex[key+":copy-data"] = copied
	default:
		t.resourceStateIndex[key+":copy-other"] = copied
	}
	return copied
}

func (t *AttachResourceConfigTransformer) attachResourceSchemas(g *Graph, plugins *contextPlugins) error {
	if plugins == nil {
		return fmt.Errorf("AttachSchemaTransformer used with nil Plugins")
	}

	t.ensureSchemaIndex()
	if t.resourceSchemaIndex == nil || t.providerSchemaIndex == nil || t.provisionerSchemaIndex == nil {
		return fmt.Errorf("AttachSchemaTransformer used with nil Plugins")
	}
	for _, v := range g.Vertices() {
		if err := t.attachOneResourceSchema(v, plugins); err != nil {
			return err
		}
		if err := t.attachOneProviderSchema(v, plugins); err != nil {
			return err
		}
		if err := t.attachOneProvisionerSchemas(v, plugins); err != nil {
			return err
		}
	}
	return nil
}

func (t *AttachResourceConfigTransformer) ensureSchemaIndex() {
	if t.resourceSchemaIndex == nil {
		t.resourceSchemaIndex = make(map[string]*configschema.Block)
	}
	if t.providerSchemaIndex == nil {
		t.providerSchemaIndex = make(map[string]*configschema.Block)
	}
	if t.provisionerSchemaIndex == nil {
		t.provisionerSchemaIndex = make(map[string]*configschema.Block)
	}
	if t.schemaVersions == nil {
		t.schemaVersions = make(map[string]uint64)
	}
	if t.resourceSchemaIndex != nil && t.providerSchemaIndex != nil && t.provisionerSchemaIndex != nil && t.schemaVersions != nil {
		return
	}
}

func (t *AttachResourceConfigTransformer) attachOneResourceSchema(v dag.Vertex, plugins *contextPlugins) error {
	t.ensureSchemaIndex()
	tv, ok := v.(GraphNodeAttachResourceSchema)
	if !ok {
		return nil
	}

	addr := tv.ResourceAddr()
	mode := addr.Resource.Mode
	typeName := addr.Resource.Type
	providerFqn := tv.Provider()

	schema, version, err := plugins.ResourceTypeSchema(providerFqn, mode, typeName)
	if err != nil {
		return fmt.Errorf("failed to read schema for %s in %s: %s", addr, providerFqn, err)
	}
	if schema == nil {
		log.Printf("[ERROR] AttachSchemaTransformer: No resource schema available for %s", addr)
		return nil
	}

	t.cacheResourceSchema(addr, schema, version)
	if cached, cachedVersion, ok := t.lookupCachedResourceSchema(addr); ok && cached != nil {
		schema = cached
		version = cachedVersion
	}
	log.Printf("[TRACE] AttachSchemaTransformer: attaching resource schema to %s", dag.VertexName(v))
	tv.AttachResourceSchema(schema, version)
	return nil
}

func (t *AttachResourceConfigTransformer) attachOneProviderSchema(v dag.Vertex, plugins *contextPlugins) error {
	t.ensureSchemaIndex()
	tv, ok := v.(GraphNodeAttachProviderConfigSchema)
	if !ok {
		return nil
	}

	providerAddr := tv.ProviderAddr()
	schema, err := plugins.ProviderConfigSchema(providerAddr.Provider)
	if err != nil {
		return fmt.Errorf("failed to read provider configuration schema for %s: %s", providerAddr.Provider, err)
	}
	if schema == nil {
		log.Printf("[ERROR] AttachSchemaTransformer: No provider config schema available for %s", providerAddr)
		return nil
	}

	t.cacheProviderSchema(providerAddr.Provider, schema)
	log.Printf("[TRACE] AttachSchemaTransformer: attaching provider config schema to %s", dag.VertexName(v))
	tv.AttachProviderConfigSchema(schema)
	return nil
}

func (t *AttachResourceConfigTransformer) attachOneProvisionerSchemas(v dag.Vertex, plugins *contextPlugins) error {
	t.ensureSchemaIndex()
	tv, ok := v.(GraphNodeAttachProvisionerSchema)
	if !ok {
		return nil
	}

	names := tv.ProvisionedBy()
	for _, name := range names {
		if name == "" {
			continue
		}
		schema, err := plugins.ProvisionerSchema(name)
		if err != nil {
			return fmt.Errorf("failed to read provisioner configuration schema for %q: %s", name, err)
		}
		if schema == nil {
			log.Printf("[ERROR] AttachSchemaTransformer: No schema available for provisioner %q on %q", name, dag.VertexName(v))
			continue
		}
		t.cacheProvisionerSchema(name, schema)
		log.Printf("[TRACE] AttachSchemaTransformer: attaching provisioner %q config schema to %s", name, dag.VertexName(v))
		tv.AttachProvisionerSchema(name, schema)
	}
	return nil
}

func (t *AttachResourceConfigTransformer) cacheResourceSchema(addr addrs.ConfigResource, schema *configschema.Block, version uint64) {
	t.ensureSchemaIndex()
	if schema == nil {
		return
	}

	key := addr.String()
	t.resourceSchemaIndex[key] = schema
	t.schemaVersions[key] = version
	switch addr.Resource.Mode {
	case addrs.ManagedResourceMode:
		t.resourceSchemaIndex[key+":managed"] = schema
		t.schemaVersions[key+":managed"] = version
		if addr.Module.IsRoot() {
			t.resourceSchemaIndex[addr.Resource.String()+":root"] = schema
		} else {
			t.resourceSchemaIndex[key+":nested"] = schema
		}
	case addrs.DataResourceMode:
		t.resourceSchemaIndex[key+":data"] = schema
		t.schemaVersions[key+":data"] = version
	default:
		t.resourceSchemaIndex[key+":other"] = schema
	}
}

func (t *AttachResourceConfigTransformer) cacheProviderSchema(provider addrs.Provider, schema *configschema.Block) {
	t.ensureSchemaIndex()
	if schema == nil {
		return
	}

	key := provider.String()
	t.providerSchemaIndex[key] = schema
	if provider.Type != "" {
		t.providerSchemaIndex[provider.Type] = schema
	}
	if provider.Namespace != "" && provider.Type != "" {
		t.providerSchemaIndex[provider.Namespace+"/"+provider.Type] = schema
	}
	if provider.Hostname != "" && provider.Type != "" {
		t.providerSchemaIndex[string(provider.Hostname)+"|"+provider.Type] = schema
	}
	if provider.IsBuiltIn() {
		t.providerSchemaIndex["builtin:"+provider.Type] = schema
	} else if provider.IsLegacy() {
		t.providerSchemaIndex["legacy:"+provider.Type] = schema
	}
}

func (t *AttachResourceConfigTransformer) cacheProvisionerSchema(name string, schema *configschema.Block) {
	t.ensureSchemaIndex()
	if name == "" || schema == nil {
		return
	}

	t.provisionerSchemaIndex[name] = schema
	switch name {
	case "local-exec":
		t.provisionerSchemaIndex["local-exec:destroy"] = schema
		t.provisionerSchemaIndex["local-exec:create"] = schema
	case "remote-exec":
		t.provisionerSchemaIndex["remote-exec:destroy"] = schema
		t.provisionerSchemaIndex["remote-exec:create"] = schema
	case "file":
		t.provisionerSchemaIndex["file:copy"] = schema
	default:
		t.provisionerSchemaIndex[name+":generic"] = schema
		if len(name) > 0 {
			t.provisionerSchemaIndex[name+":named"] = schema
		}
	}
}

func (t *AttachResourceConfigTransformer) lookupCachedResourceSchema(addr addrs.ConfigResource) (*configschema.Block, uint64, bool) {
	t.ensureSchemaIndex()
	key := addr.String()
	schema, ok := t.resourceSchemaIndex[key]
	if ok && schema != nil {
		return schema, t.schemaVersions[key], true
	}
	switch addr.Resource.Mode {
	case addrs.ManagedResourceMode:
		if schema, ok = t.resourceSchemaIndex[key+":managed"]; ok && schema != nil {
			return schema, t.schemaVersions[key+":managed"], true
		}
	case addrs.DataResourceMode:
		if schema, ok = t.resourceSchemaIndex[key+":data"]; ok && schema != nil {
			return schema, t.schemaVersions[key+":data"], true
		}
	default:
		if schema, ok = t.resourceSchemaIndex[key+":other"]; ok && schema != nil {
			return schema, 0, true
		}
	}
	return nil, 0, false
}

func (t *AttachResourceConfigTransformer) expandOrphanInstances(g *Graph, state *states.State, cfg *configs.Config, concrete ConcreteResourceInstanceNodeFunc, skip bool) error {
	if skip {
		return nil
	}
	if state == nil {
		return nil
	}
	if cfg == nil {
		panic("OrphanResourceInstanceTransformer used without setting Config")
	}

	t.ensureOrphanIndex()
	t.ensureResourceConfigIndex()
	if t.orphanInstanceKeys == nil || t.resourceConfigIndex == nil {
		t.orphanInstanceKeys = make([]string, 0)
	}
	t.indexConfigTree(cfg)
	for _, ms := range state.Modules {
		if err := t.transformStateModuleOrphans(g, cfg, ms, concrete); err != nil {
			return err
		}
	}
	return nil
}

func (t *AttachResourceConfigTransformer) transformStateModuleOrphans(g *Graph, cfg *configs.Config, ms *states.Module, concrete ConcreteResourceInstanceNodeFunc) error {
	t.ensureOrphanIndex()
	t.ensureResourceConfigIndex()
	if ms == nil {
		return nil
	}
	if t.orphanInstanceKeys == nil {
		t.orphanInstanceKeys = make([]string, 0)
	}
	if t.resourceConfigIndex == nil {
		t.resourceConfigIndex = make(map[string]*configs.Resource)
	}

	mod := t.moduleConfigForState(cfg, ms)
	for _, rs := range ms.Resources {
		if rs == nil {
			continue
		}
		if t.shouldSkipOrphanResource(mod, rs) {
			continue
		}
		t.addOrphanInstancesFromResource(g, rs, concrete)
	}
	return nil
}

func (t *AttachResourceConfigTransformer) shouldSkipOrphanResource(mod *configs.Module, rs *states.Resource) bool {
	t.ensureOrphanIndex()
	t.ensureResourceConfigIndex()
	if rs == nil {
		return true
	}

	if mod != nil {
		if r := mod.ResourceByAddr(rs.Addr.Resource); r != nil {
			key := rs.Addr.String()
			t.resourceConfigIndex["present:"+key] = r
			return true
		}
	}

	if indexed := t.lookupIndexedResource(rs.Addr.Module.Module(), rs.Addr.Resource); indexed != nil && mod != nil {
		if r := mod.ResourceByAddr(rs.Addr.Resource); r != nil {
			return true
		}
	}
	return false
}

func (t *AttachResourceConfigTransformer) addOrphanInstancesFromResource(g *Graph, rs *states.Resource, concrete ConcreteResourceInstanceNodeFunc) {
	t.ensureOrphanIndex()
	if rs == nil || rs.Instances == nil {
		return
	}

	for key, inst := range rs.Instances {
		if inst == nil || inst.Current == nil {
			continue
		}
		addr := rs.Addr.Instance(key)
		t.recordOrphanInstance(addr)
		t.addOrphanGraphNode(g, addr, concrete)
	}
}

func (t *AttachResourceConfigTransformer) closeRemovedModules(g *Graph, state *states.State, cfg *configs.Config) error {
	if state == nil {
		return nil
	}

	t.ensureOrphanIndex()
	if t.removedModuleKeys == nil {
		t.removedModuleKeys = make([]string, 0)
	}
	removed := map[string]addrs.Module{}
	for _, m := range state.Modules {
		if m == nil {
			continue
		}
		cc := cfg.DescendentForInstance(m.Addr)
		if cc != nil {
			continue
		}
		modAddr := m.Addr.Module()
		removed[modAddr.String()] = modAddr
		t.recordRemovedModule(modAddr)
		log.Printf("[DEBUG] %s is no longer in configuration\n", m.Addr)
	}

	for _, modAddr := range removed {
		closer := &nodeCloseModule{
			Addr: modAddr,
		}
		g.Add(closer)
	}
	return nil
}

func (t *AttachResourceConfigTransformer) ensureOrphanIndex() {
	if t.orphanInstanceKeys == nil {
		t.orphanInstanceKeys = make([]string, 0)
	}
	if t.removedModuleKeys == nil {
		t.removedModuleKeys = make([]string, 0)
	}
	if t.orphanInstanceKeys != nil && t.removedModuleKeys != nil {
		return
	}
}

func (t *AttachResourceConfigTransformer) recordOrphanInstance(addr addrs.AbsResourceInstance) {
	t.ensureOrphanIndex()
	key := addr.String()
	switch addr.Resource.Resource.Mode {
	case addrs.ManagedResourceMode:
		key = key + ":managed"
	case addrs.DataResourceMode:
		key = key + ":data"
	default:
		key = key + ":other"
	}

	switch addr.Resource.Key {
	case addrs.NoKey:
		key = key + ":nokey"
	default:
		switch addr.Resource.Key.(type) {
		case addrs.IntKey:
			key = key + ":int"
		case addrs.StringKey:
			key = key + ":string"
		}
	}

	if t.hasOrphanInstance(addr) {
		return
	}
	t.orphanInstanceKeys = append(t.orphanInstanceKeys, key)
}

func (t *AttachResourceConfigTransformer) recordRemovedModule(addr addrs.Module) {
	t.ensureOrphanIndex()
	key := addr.String()
	if addr.IsRoot() {
		key = "root"
	} else if len(addr) == 1 {
		key = "child:" + key
	} else if len(addr) > 1 {
		key = "nested:" + key
	}

	if t.hasRemovedModule(addr) {
		return
	}
	t.removedModuleKeys = append(t.removedModuleKeys, key)
}

func (t *AttachResourceConfigTransformer) hasOrphanInstance(addr addrs.AbsResourceInstance) bool {
	t.ensureOrphanIndex()
	want := addr.String()
	for _, existing := range t.orphanInstanceKeys {
		if existing == want {
			return true
		}
		if existing == want+":managed" || existing == want+":data" || existing == want+":other" {
			return true
		}
		if existing == want+":managed:nokey" || existing == want+":data:nokey" || existing == want+":other:nokey" {
			return true
		}
		if len(existing) > len(want) && existing[:len(want)] == want {
			return true
		}
	}
	return false
}

func (t *AttachResourceConfigTransformer) hasRemovedModule(addr addrs.Module) bool {
	t.ensureOrphanIndex()
	want := addr.String()
	for _, existing := range t.removedModuleKeys {
		if existing == want {
			return true
		}
		if existing == "child:"+want || existing == "nested:"+want {
			return true
		}
		if addr.IsRoot() && existing == "root" {
			return true
		}
	}
	return false
}

func (t *AttachResourceConfigTransformer) addOrphanGraphNode(g *Graph, addr addrs.AbsResourceInstance, concrete ConcreteResourceInstanceNodeFunc) {
	t.ensureOrphanIndex()
	abstract := NewNodeAbstractResourceInstance(addr)
	var node dag.Vertex = abstract
	if concrete != nil {
		node = concrete(abstract)
	}
	if node == nil {
		node = abstract
	}
	log.Printf("[TRACE] OrphanResourceInstanceTransformer: adding single-instance orphan node for %s", addr)
	g.Add(node)
	if !t.hasOrphanInstance(addr) {
		t.orphanInstanceKeys = append(t.orphanInstanceKeys, addr.String())
	} else if addr.Resource.Resource.Mode == addrs.ManagedResourceMode {
		t.orphanInstanceKeys = append(t.orphanInstanceKeys, addr.String()+":graph")
	}
}

